} from '@ionic/react';
import { add, create, trash, informationCircleOutline, bulbOutline } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import {
  FactoryRunUsage,
  getAllFactoryRunUsages,
  getFactoryRunUsage,
  createFactoryRunUsage,
  updateFactoryRunUsage,
  deleteFactoryRunUsage,
} from '../api/factoryRunUsageApi';
import { InputInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FactoryRunUsageForm {
  factoryRunRef: string;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  costUSD: number;
  modelName: string;
  timestamp: string;
}

const initialFormState: FactoryRunUsageForm = {
  factoryRunRef: '',
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
  costUSD: 0.00,
  modelName: '',
  timestamp: new Date().toISOString().slice(0, 16), // YYYY-MM-DDTHH:mm for datetime-local
};

const ITEMS_PER_PAGE = 20;

const FactoryRunUsagePage: React.FC = () => {
  const { roleCode } = useUser();
  const canEdit = roleCode === 'admin';

  const [factoryRunUsages, setFactoryRunUsages] = useState<FactoryRunUsage[]>([]);
  const [filteredUsages, setFilteredUsages] = useState<FactoryRunUsage[]>([]);
  const [displayUsages, setDisplayUsages] = useState<FactoryRunUsage[]>([]);
  const [page, setPage] = useState(1);

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const [showAddEditModal, setShowAddEditModal] = useState(false);
  const [selectedUsage, setSelectedUsage] = useState<FactoryRunUsage | null>(null);
  const [formState, setFormState] = useState<FactoryRunUsageForm>(initialFormState);
  const [formErrors, setFormErrors] = useState<Partial<Record<keyof FactoryRunUsageForm, string>>>({});

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [usageToDeleteId, setUsageToDeleteId] = useState<number | null>(null);

  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement>(null);

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const validateForm = (): boolean => {
    const errors: Partial<Record<keyof FactoryRunUsageForm, string>> = {};
    if (!formState.factoryRunRef) errors.factoryRunRef = 'Referencia de ejecución es requerida.';
    if (formState.promptTokens < 0) errors.promptTokens = 'Tokens de prompt no pueden ser negativos.';
    if (formState.completionTokens < 0) errors.completionTokens = 'Tokens de completado no pueden ser negativos.';
    if (formState.totalTokens < 0) errors.totalTokens = 'Total de tokens no puede ser negativo.';
    if (formState.costUSD < 0) errors.costUSD = 'Costo no puede ser negativo.';
    if (!formState.modelName) errors.modelName = 'Nombre del modelo es requerido.';
    if (!formState.timestamp) errors.timestamp = 'Fecha y hora es requerida.';
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const fetchFactoryRunUsages = async (clearExisting = false) => {
    setLoading(true);
    try {
      const data = await getAllFactoryRunUsages();
      setFactoryRunUsages(data);
      if (clearExisting) {
        setDisplayUsages([]);
        setPage(1);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar usos de Factory Run');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFactoryRunUsages(true);
  }, []);

  useEffect(() => {
    const lowerCaseSearchTerm = searchTerm.toLowerCase();
    const filtered = factoryRunUsages.filter(
      (usage) =>
        usage.factoryRunRef.toLowerCase().includes(lowerCaseSearchTerm) ||
        usage.modelName.toLowerCase().includes(lowerCaseSearchTerm) ||
        usage.costUSD.toFixed(2).includes(lowerCaseSearchTerm)
    );
    setFilteredUsages(filtered);
    setDisplayUsages(filtered.slice(0, ITEMS_PER_PAGE));
    setPage(1);
    if (infiniteScrollRef.current) {
      infiniteScrollRef.current.complete();
      infiniteScrollRef.current.disabled = filtered.length <= ITEMS_PER_PAGE;
    }
  }, [searchTerm, factoryRunUsages]);

  const loadMoreItems = (ev: CustomEvent<void>) => {
    if (displayUsages.length < filteredUsages.length) {
      const nextPage = page + 1;
      const newItems = filteredUsages.slice(0, nextPage * ITEMS_PER_PAGE);
      setDisplayUsages(newItems);
      setPage(nextPage);
    }
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleRefresh = async (event: CustomEvent) => {
    await fetchFactoryRunUsages(true);
    event.detail.complete();
  };

  const openAddModal = () => {
    setSelectedUsage(null);
    setFormState(initialFormState);
    setFormErrors({});
    setShowAddEditModal(true);
  };

  const openEditModal = async (usage: FactoryRunUsage) => {
    setLoading(true);
    try {
      const fetchedUsage = await getFactoryRunUsage(usage.factoryRunUsageId);
      if (fetchedUsage) {
        setSelectedUsage(fetchedUsage);
        setFormState({
          factoryRunRef: fetchedUsage.factoryRunRef,
          promptTokens: fetchedUsage.promptTokens,
          completionTokens: fetchedUsage.completionTokens,
          totalTokens: fetchedUsage.totalTokens,
          costUSD: fetchedUsage.costUSD,
          modelName: fetchedUsage.modelName,
          timestamp: new Date(fetchedUsage.timestamp).toISOString().slice(0, 16),
        });
        setFormErrors({});
        setShowAddEditModal(true);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar datos para edición');
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!validateForm()) {
      setError('Por favor, corrige los errores en el formulario.');
      return;
    }

    setSaving(true);
    try {
      if (selectedUsage) {
        await updateFactoryRunUsage(selectedUsage.factoryRunUsageId, formState);
        setError('Uso de Factory Run actualizado con éxito.');
      } else {
        await createFactoryRunUsage(formState);
        setError('Uso de Factory Run creado con éxito.');
      }
      setShowAddEditModal(false);
      await fetchFactoryRunUsages(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el uso de Factory Run.');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (id: number) => {
    setUsageToDeleteId(id);
    setShowDeleteAlert(true);
  };

  const confirmDelete = async () => {
    if (usageToDeleteId === null) return;
    setLoading(true);
    try {
      await deleteFactoryRunUsage(usageToDeleteId);
      setError('Uso de Factory Run eliminado con éxito.');
      await fetchFactoryRunUsages(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar el uso de Factory Run.');
    } finally {
      setLoading(false);
      setUsageToDeleteId(null);
    }
  };

  return (
    <IonPage className="factoryrunusage-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Uso LLM — Factory GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonRefresher slot="fixed" onIonRefresh={handleRefresh}>
          <IonRefresherContent></IonRefresherContent>
        </IonRefresher>

        <IonSearchbar
          className="factoryrunusage-searchbar"
          value={searchTerm}
          onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSearchTerm(e.detail.value!)}
          placeholder="Buscar por referencia, modelo o costo"
          debounce={300}
        />

        {loading && factoryRunUsages.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <IonSpinner name="crescent" />
            <p>Cargando usos de Factory Run...</p>
          </div>
        ) : filteredUsages.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <IonIcon icon={informationCircleOutline} size="large" color="medium" />
            <p>No se encontraron usos de Factory Run.</p>
            {canEdit && (
              <IonButton expand="block" onClick={openAddModal}>
                <IonIcon icon={add} slot="start" />
                Agregar nuevo uso
              </IonButton>
            )}
          </div>
        ) : (
          <IonList className="factoryrunusage-list">
            {displayUsages.map((usage) => (
              <IonItem
                key={usage.factoryRunUsageId}
                button
                onClick={() => openEditModal(usage)}
                className="factoryrunusage-item"
              >
                <IonLabel>
                  <h2>Ref: {usage.factoryRunRef}</h2>
                  <p>Modelo: {usage.modelName}</p>
                  <p>Tokens: {usage.totalTokens} ({usage.promptTokens} prompt, {usage.completionTokens} completion)</p>
                  <p>Costo: ${usage.costUSD.toFixed(2)} USD</p>
                  <p>Timestamp: {toHermosillo(usage.timestamp)}</p>
                  <p>Creado: {toHermosillo(usage.created_At)}</p>
                  {usage.updated_at && <p>Actualizado: {toHermosillo(usage.updated_at)}</p>}
                </IonLabel>
                {canEdit && (
                  <IonButton fill="clear" slot="end" color="danger" onClick={(e) => {
                    e.stopPropagation(); // Prevent item click from triggering
                    handleDeleteClick(usage.factoryRunUsageId);
                  }}>
                    <IonIcon icon={trash} />
                  </IonButton>
                )}
              </IonItem>
            ))}
          </IonList>
        )}

        <IonInfiniteScroll
          ref={infiniteScrollRef}
          onIonInfinite={loadMoreItems}
          threshold="100px"
          disabled={displayUsages.length >= filteredUsages.length}
        >
          <IonInfiniteScrollContent loadingText="Cargando más usos..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        {canEdit && (
          <IonFab vertical="bottom" horizontal="end" slot="fixed">
