            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete, cssClass: 'danger' },
          ]}
        />

        <IonLoading isOpen={loading && !saving} message={'Cargando...'} />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.includes('Error') ? 'danger' : 'success'}
        />
      </IonContent>
    </IonPage>
  );
};

export default FactoryRunUsagePage;
